var QUESTOES_REDACAO_OFICIAL = [{"id":17970,"enunciado":"O título, o formato e o assunto do texto permitem que ele seja classificado como reprodução exemplar de uma correspondência oficial do século XIX no Brasil.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2009,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":17971,"enunciado":"O texto prima pela clareza, pela concisão e pelo necessário domínio da norma culta da língua portuguesa, preconizados pelas normas atuais da correspondência oficial.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2009,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":17972,"enunciado":"A aproximação entre o formato de correspondência usada em órgãos públicos e o assunto de âmbito da vida privada, que caracteriza o estilo irônico da carta do desembargador X, é um procedimento inaceitável segundo os parâmetros atuais da redação oficial.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2009,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":17973,"enunciado":"O fato de o objetivo da carta do desembargador X estar claramente expresso no final da missiva demonstra uma característica do texto que é exigida pelas normas atuais de correspondência oficial: a objetividade.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2009,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":17974,"enunciado":"O acontecimento informado pelo remetente ao destinatário - a visita de Alcebíades - ocorreu, como ele afirma, graças à sua transposição para o tempo e lugar da obra de Plutarco.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2009,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":17975,"enunciado":"Em \"padeci esta devoção ao grego\" (.7), não haveria prejuízo para o sentido e para a correção gramatical do texto, se fosse empregada a palavra desta em lugar de \"esta\".","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2009,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":18762,"enunciado":"O fragmento em questão está correto quanto à observância dos requisitos exigidos na redação e padronização desse tipo de correspondência oficial.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":21245,"enunciado":"A respeito da redação de correspondências oficiais, julgue o próximo item.\n\nCaso uma servidora pública aposentada pretenda ingressar com requerimento de revisão do processo de sua aposentadoria no departamento de recursos humanos do órgão em que trabalhou e, por estar impossibilitada de fazê-lo pessoalmente, queira nomear pessoa de sua confiança para representá-la, junto àquele departamento, nos atos que se façam necessários à referida solicitação, a servidora deverá redigir uma declaração, nomeando a pessoa escolhida, para que esta possa representá-la nos citados atos","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":28397,"enunciado":"O final de um relatório sobre o tema do texto respeitaria a norma culta e as normas de redação de documentos oficiais se fosse assim redigido: Ante do exposto, recomenda-se as instituições financeiras esforços conjuntos no sentido de manter a rentabilidade de seus clientes.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":85352,"enunciado":"Analise: 1. Atendendo à solicitação contida no expediente acima referido, vimos encaminhar a V. Sa. as informações referentes ao andamento dos serviços sob responsabilidade deste setor. 2. Esclarecemos que estão sendo tomadas todas as medidas necessárias para o cumprimento dos prazos estipulados e o atingimento das metas estabelecidas. A redação do documento acima indica tratar-se","opcoes":["do encaminhamento de uma ata.","do início de um requerimento.","de trecho do corpo de um ofício.","da introdução de um relatório.","do fecho de um memorando."],"correta":2,"explicacao":"Gabarito: <strong>de trecho do corpo de um ofício.</strong>.","banca":"FCC","ano":2011,"temas_relacionados":["redacao_oficial"]},{"id":255583,"enunciado":"Com base na figura do texto V, julgue os itens subseqüentes, relativos ao Word 2000 e às idéias do texto do documento em edição.\n\nUm dos recursos utilizados no texto para manter a coerência com o gênero de documento declaração, no qual deve predominar a objetividade, consiste em garantir a impessoalidade por meio da escolha de sujeitos institucionais.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2002,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":277569,"enunciado":"O principal meio de punir as empresas infratoras do sistema de telefonia é a aplicação de multas as quais devem ser calculadas a partir da lucratividade anual aferida pela instituição infratora. Verifica-se que, pela recorrência das infrações, tal medida deverá ser aplicada com mais rigor.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2012,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":277570,"enunciado":"As correspondências feitas por email são válidas como correspondências oficiais, desde que a identidade do remetente seja atestada por meio de certificação digital.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2012,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":277571,"enunciado":"Embora as comunicações oficiais sejam feitas em nome do serviço público, tais documentos geralmente contêm impressões individuais de quem redige a comunicação, o que não fere o princípio da impessoalidade, visto que eles são assinados pela autoridade que os expede.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2012,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":318350,"enunciado":"Acerca das características gerais dos diversos tipos de comunicação oficial, julgue os itens seguintes.\n\nNas comunicações oficiais dirigidas a ministros de tribunais superiores, deve-se empregar o vocativo Senhor Ministro.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2013,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":318351,"enunciado":"Acerca das características gerais dos diversos tipos de comunicação oficial, julgue os itens seguintes.\n\nComunicações oficiais emitidas pelo chefe do Poder Judiciário e pelo chefe do Poder Legislativo devem conter, ao final, no espaço reservado à identificação do signatário, o nome e o cargo da autoridade que as expede","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2013,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":318352,"enunciado":"Acerca das características gerais dos diversos tipos de comunicação oficial, julgue os itens seguintes.\n\nA exposição de motivos consiste na principal forma de comunicação entre os ministros de Estado e o presidente da República.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2013,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":318353,"enunciado":"Acerca das características gerais dos diversos tipos de comunicação oficial, julgue os itens seguintes.\n\nComunicações oficiais, utilizadas para a comunicação entre órgãos do serviço público ou entre órgãos do serviço público e o público em geral, podem ser emitidas tanto pela administração pública quanto pelos cidadãos.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2013,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":318354,"enunciado":"Acerca das características gerais dos diversos tipos de comunicação oficial, julgue os itens seguintes.\n\nPara atender à exigência de uniformidade, um dos atributos da redação oficial, os expedientes oficiais de qualquer tipo devem ser estruturados conforme o padrão ofício de diagramação.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2013,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":323608,"enunciado":"Em relação às exigências da redação de correspondências oficiais, julgue o   item   que se segue.\n\n\nO trecho a seguir está adequado e correto para compor um memorando: Nos termos do “Programa de modernização e informatização da Agência Nacional de Saúde Suplementar”, solicito a Vossa Senhoria a instalação de dois novos computadores no setor de protocolo para atender à demanda e melhorar a qualidade dos serviços prestados ao público.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2013,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":323609,"enunciado":"Em relação às exigências da redação de correspondências oficiais, julgue o   item  que se segue..\n\n\nO trecho a seguir está adequado e correto para compor um ofício: Viemos informar que vamos estar enviando oportunamente os relatórios solicitados via email, com todas as informações referentes ao desenvolvimento das auditorias citadas.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2013,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":323610,"enunciado":"Em relação às exigências da redação de correspondências oficiais, julgue o  item  que se segue.\n\n\nA forma de tratamento Magnífico destina-se a autoridades do Poder Legislativo, principalmente ao presidente da Câmara dos Deputados e ao do Senado Federal.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2013,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":323611,"enunciado":"Em relação às exigências da redação de correspondências oficiais, julgue o  item que se segue.\n\nOs ministros de Estado recebem o tratamento de Vossa Excelência, e o vocativo empregado em comunicações a eles dirigidas deve ser Excelentíssimo Senhor Ministro.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2013,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":323612,"enunciado":"Em relação às exigências da redação de correspondências oficiais, julgue o  item  que se segue.\n\n\nO Manual de Redação da Presidência da República, com o objetivo de simplificar e uniformizar o padrão dos fechos de comunicações oficiais, estabelece que, para autoridades superiores, seja utilizado o fecho Respeitosamente, e que, para autoridades de mesma hierarquia ou de hierarquia inferior, seja adotado o fecho Atenciosamente.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2013,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":326891,"enunciado":"No que se refere a aspectos gerais das correspondências oficiais, julgue os itens de 17 a 22 com base no Manual de Redação da Presidência da República.\n\n\nTratando-se de ofício, a numeração das páginas deve iniciar-se a partir da segunda. Nesse caso, os números podem ser impressos em ambas as faces do papel, desde que as distâncias das margens esquerda e direita sejam invertidas nas páginas pares","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2013,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":326892,"enunciado":"No que se refere a aspectos gerais das correspondências oficiais, julgue os itens de 17 a 22 com base no Manual de Redação da Presidência da República.\n\n\nPor constituírem parte indispensável do ofício, a identificação e a assinatura do signatário devem constar em página isolada do expediente, o que lhes confere o devido destaque.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2013,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":326893,"enunciado":"No que se refere a aspectos gerais das correspondências oficiais, julgue os itens de 17 a 22 com base no Manual de Redação da Presidência da República.\n\n\nEm comunicações oficiais dirigidas ao ministro da Integração Nacional, devem-se empregar o pronome de tratamento “Vossa Excelência” e o vocativo “Excelentíssimo Senhor Ministro”.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2013,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":326894,"enunciado":"No que se refere a aspectos gerais das correspondências oficiais, julgue os itens de 17 a 22 com base no Manual de Redação da Presidência da República.\n\n\nEm ofício destinado ao envio de documentos, deve-se iniciar o texto com referência ao expediente que os tenha solicitado; ou, no caso de a remessa de documento não ter sido solicitada, o texto deve iniciar-se com a informação do motivo da comunicação, seguida dos dados completos do documento encaminhado e da razão pela qual ele está sendo remetido.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2013,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":326895,"enunciado":"No que se refere a aspectos gerais das correspondências oficiais, julgue os itens de 17 a 22 com base no Manual de Redação da Presidência da República.\n\n\nDados o conteúdo e a estrutura do documento acima apresentado, é correto concluir que esse documento é uma exposição de motivos.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2013,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":326896,"enunciado":"No que se refere a aspectos gerais das correspondências oficiais, julgue os itens de 17 a 22 com base no Manual de Redação da Presidência da República.\n\n\nJuntamente com documentos enviados por fax, recomenda-se que se encaminhe folha de rosto em que constem os dados de identificação da mensagem a ser enviada.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2013,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":342988,"enunciado":"Com base nas normas de redação de documentos oficiais do Poder Executivo, julgue os itens a seguir com relação ao correto preenchimento dos espaços designados pelos colchetes.\n\nO segundo colchete (l.3) deve ser preenchido com o vocativo “Senhor Senador,”.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2009,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":342989,"enunciado":"Com base nas normas de redação de documentos oficiais do Poder Executivo, julgue os itens a seguir com relação ao correto preenchimento dos espaços designados pelos colchetes.\n\nO fecho do expediente (l.10) deve conter as saudações Abraços ou Cumprimentos protocolares, a depender do grau de intimidade entre signatário e destinatário.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2009,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":342990,"enunciado":"Com base nas normas de redação de documentos oficiais do Poder Executivo, julgue os itens a seguir com relação ao correto preenchimento dos espaços designados pelos colchetes.\n\nPor se tratar de convite oficial, o tipo de expediente recomendado é o memorando, devendo o primeiro colchete (l.1) ser preenchido com o termo Memorando ou com a abreviatura Memo.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2009,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":342991,"enunciado":"Tendo como referência o texto apresentado, julgue os itens subsequentes quanto à diagramação (alinhamento na página) ou ao emprego dos pronomes de tratamento recomendado na redação de documentos oficiais.\n\n\nNo âmbito do Poder Executivo, conforme normatização incidente sobre a redação de fórmulas de saudação, é desaconselhável o emprego da expressão “reitero meu sentimento de apreço e estima por Vossa Excelência” (l.8-9).","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2009,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":342992,"enunciado":"Tendo como referência o texto apresentado, julgue os itens subsequentes quanto à diagramação (alinhamento na página) ou ao emprego dos pronomes de tratamento recomendado na redação de documentos oficiais.\n\nNos documentos oficiais que seguem o padrão ofício, o endereçamento deve constar no final da página, à esquerda, se o documento contiver apenas uma página, como é o caso do texto apresentado (l.14-17); se contiver mais de uma, deve constar na última página.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2009,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":342993,"enunciado":"Tendo como referência o texto apresentado, julgue os itens subsequentes quanto à diagramação (alinhamento na página) ou ao emprego dos pronomes de tratamento recomendado na redação de documentos oficiais.\n\nA indicação de local e data (l.2) deve estar alinhada à direita, coincidindo o ponto-final com a borda da margem direita.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2009,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":342994,"enunciado":"Tendo como referência o texto apresentado, julgue os itens subsequentes quanto à diagramação (alinhamento na página) ou ao emprego dos pronomes de tratamento recomendado na redação de documentos oficiais.\n\nPara se efetuar a concordância correta com a forma de tratamento “Vossa Excelência” (l.4), deve ser empregado, em substituição a “sua” (l.8), o pronome vossa, de que resultará a expressão vossa presença.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2009,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":342995,"enunciado":"Julgue os itens subsequentes com base nas prescrições que regem a redação de documentos oficiais.\n\nPor ser suscetível a falsificações, o correio eletrônico (e-mail) não tem valor documental nos órgãos do Poder Executivo, sendo usado apenas nas comunicações de caráter particular entre servidores.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2009,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":342996,"enunciado":"Julgue os itens subsequentes com base nas prescrições que regem a redação de documentos oficiais.\n\nEm comunicação dirigida a um juiz, deve ser empregado o vocativo “Senhor Juiz,”.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2009,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":342997,"enunciado":"Julgue os itens subsequentes com base nas prescrições que regem a redação de documentos oficiais.\n\nPara requerimentos, padronizou-se o seguinte fecho: Nesses termos, pede deferimento.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2009,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":359782,"enunciado":"Levando em consideração as normas constantes do Manual de Redação da Presidência da República, julgue os seguintes itens.\n\nO texto das comunicações oficiais dirigidas a ministro de Estado deve ser precedido pelo vocativo “Senhor Ministro”.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":359783,"enunciado":"Levando em consideração as normas constantes do Manual de Redação da Presidência da República, julgue os seguintes itens.\n\nO ofício é a forma de comunicação indicada para a comunicação entre ministérios.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":359784,"enunciado":"Levando em consideração as normas constantes do Manual de Redação da Presidência da República, julgue os seguintes itens.\n\nO aviso é uma modalidade de comunicação expedida somente por ministros de Estado para autoridades de mesma hierarquia.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":359785,"enunciado":"Levando em consideração as normas constantes do Manual de Redação da Presidência da República, julgue os seguintes itens.\n\nEm “Vossa Excelência deve estar satisfeita com os resultados das negociações”, o adjetivo estará corretamente empregado se dirigido a ministro de Estado do sexo masculino, pois o termo “satisfeita” deve concordar com a locução pronominal de tratamento “Vossa Excelência”.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":359786,"enunciado":"Levando em consideração as normas constantes do Manual de Redação da Presidência da República, julgue os seguintes itens.\n\nAutoridades de mesma hierarquia, como os ministros de Estado, devem utilizar o memorando nas comunicações para tratar de assuntos oficiais entre si.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":377377,"enunciado":"Na mensagem eletrônica enviada, para facilitar a organização documental, Machado deveria ter dado informações detalhadas acerca do arquivo anexado, e tê-lo encaminhado preferencialmente no formato pdf.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":377378,"enunciado":"O e-mail encaminhado por Machado, além de estar inadequado quanto ao recurso “confirmação de leitura”, não pode ser aceito como documento original.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":377379,"enunciado":"O expediente oficial e-mail apresenta flexibilidade tanto na forma quanto na linguagem, o que tornaria adequada à situação em análise a seguinte mensagem: “Prezado Alencar, mande rápido, por favor, os materiais descritos na lista anexa. Cordialmente, Machado”.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":456107,"enunciado":"Início de requerimento:","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2000,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":456108,"enunciado":"Início de memorando:","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2000,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":456109,"enunciado":"Início de ata:","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2000,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":456110,"enunciado":"Fecho de ofício:","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2000,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":456111,"enunciado":"Fecho de parecer:","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2000,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":456112,"enunciado":"Exceto pelo emprego de períodos sintáticos longos, o fragmento respeita as normas de concisão e objetividade recomendadas pelo Manual de Redação da Presidência da República.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2000,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":456113,"enunciado":"No fragmento, para que a característica de clareza seja observada, deve não apenas ser reformulado o nível sintático como também deve haver mais precisão na organização das idéias.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2000,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":456114,"enunciado":"Embora os níveis gráfico e lexical estejam corretos, o texto desrespeita as regras do padrão culto da linguagem no nível sintático.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2000,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":456115,"enunciado":"O texto não obedece às características de formalidade e de impessoalidade que devem nortear toda correspondência oficial para que esta adquira uniformidade.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2000,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":456116,"enunciado":"As formas de tratamento empregadas no texto revelam um caráter de respeitosa formalidade e estão de acordo com as recomendações para textos oficiais.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2000,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":483903,"enunciado":"Goiânia, 21 de janeiro de 2015.\n\nAo Senhor Chefe do Setor de Estágios (SEst)\n\nAssunto: Novos procedimentos para envio de frequência de estagiários\n\n1. Para garantir mais agilidade em relação ao pagamento da bolsa-estágio, informo que, a partir do mês de abril deste ano, serão adotados novos procedimentos para o envio da frequência dos estagiários ao Setor de Pessoal (SePes).\n\n2. A frequência mensal de cada estagiário deverá ser enviada para o endereço de email do SePes até o quinto dia útil de cada mês.\n\n3. As informações do email devem ser complementadas com anexo contendo a planilha de frequência de estagiários, carimbada e assinada pelo chefe do SEst e pelos estagiários.\n\n4. A observância desses procedimentos é essencial para evitar atrasos no pagamento da bolsa.\n\nAtenciosamente,\n\n(espaço para assinatura)\n[nome do signatário]\nChefe do Setor de Pessoal\n\nCom base no Manual de Redação da Presidência da República, julgue o item seguinte, relativos à correspondência oficial hipotética apresentada.\n\nA finalidade comunicativa do expediente em apreço é anunciar novas diretrizes a serem seguidas pelo SEst na comunicação da frequência dos estagiários ao SePes","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2015,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":483904,"enunciado":"Goiânia, 21 de janeiro de 2015.\n\nAo Senhor Chefe do Setor de Estágios (SEst) Assunto: Novos procedimentos para envio de frequência de estagiários\n\n1. Para garantir mais agilidade em relação ao pagamento da bolsa-estágio, informo que, a partir do mês de abril deste ano, serão adotados novos procedimentos para o envio da frequência dos estagiários ao Setor de Pessoal (SePes).\n\n2. A frequência mensal de cada estagiário deverá ser enviada para o endereço de email do SePes até o quinto dia útil de cada mês.\n\n3. As informações do email devem ser complementadas com anexo contendo a planilha de frequência de estagiários, carimbada e assinada pelo chefe do SEst e pelos estagiários.\n\n4. A observância desses procedimentos é essencial para evitar atrasos no pagamento da bolsa.\n\n                                      Atenciosamente,\n\n                                                                     (espaço para assinatura)\n                                                                     [nome do signatário]\n                                                                     Chefe do Setor de Pessoal\n\nCom base no Manual de Redação da Presidência da República, julgue o  item  seguinte , relativo  à correspondência oficial hipotética apresentada.\n\nA substituição do fecho “Atenciosamente\" por Respeitosamente, apesar de denotar impessoalidade, característica dos textos oficiais, seria inadequada no expediente oficial em questão.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2015,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":483905,"enunciado":"Goiânia, 21 de janeiro de 2015.\n\nAo Senhor Chefe do Setor de Estágios (SEst) Assunto: Novos procedimentos para envio de frequência de estagiários\n\n1. Para garantir mais agilidade em relação ao pagamento da bolsa-estágio, informo que, a partir do mês de abril deste ano, serão adotados novos procedimentos para o envio da frequência dos estagiários ao Setor de Pessoal (SePes).\n\n2. A frequência mensal de cada estagiário deverá ser enviada para o endereço de email do SePes até o quinto dia útil de cada mês.\n\n3. As informações do email devem ser complementadas com anexo contendo a planilha de frequência de estagiários, carimbada e assinada pelo chefe do SEst e pelos estagiários.\n\n4. A observância desses procedimentos é essencial para evitar atrasos no pagamento da bolsa.\n\n        Atenciosamente,\n\n                                                       (espaço para assinatura)\n                                                       [nome do signatário]\n                                                       Chefe do Setor de Pessoal\n\nCom base no Manual de Redação da Presidência da República, julgue o  itens seguinte , relativo à correspondência oficial hipotética apresentada.\n\nNo tipo de texto oficial ilustrado, a assinatura e a indicação do cargo da autoridade que o expede constituem informações obrigatórias para a identificação do signatário, ao passo que o nome dessa autoridade constitui informação opcional.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2015,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":483906,"enunciado":"Goiânia, 21 de janeiro de 2015.\n\nAo Senhor Chefe do Setor de Estágios (SEst) Assunto: Novos procedimentos para envio de frequência de estagiários\n\n1. Para garantir mais agilidade em relação ao pagamento da bolsa-estágio, informo que, a partir do mês de abril deste ano, serão adotados novos procedimentos para o envio da frequência dos estagiários ao Setor de Pessoal (SePes).\n\n2. A frequência mensal de cada estagiário deverá ser enviada para o endereço de email do SePes até o quinto dia útil de cada mês.\n\n3. As informações do email devem ser complementadas com anexo contendo a planilha de frequência de estagiários, carimbada e assinada pelo chefe do SEst e pelos estagiários.\n\n4. A observância desses procedimentos é essencial para evitar atrasos no pagamento da bolsa.\n\nAtenciosamente,\n\n(espaço para assinatura)\n[nome do signatário]\nChefe do Setor de Pessoal\n\nCom base no Manual de Redação da Presidência da República, julgue os itens seguintes, relativos à correspondência oficial hipotética apresentada.\n\nNa situação considerada, quando for enviado, o email com a frequência dos estagiários terá seu valor documental garantido por duas razões: por envolver dois setores de um mesmo órgão público e por conter informações de caráter meramente administrativo.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2015,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":483907,"enunciado":"Goiânia, 21 de janeiro de 2015.\n\nAo Senhor Chefe do Setor de Estágios (SEst) Assunto: Novos procedimentos para envio de frequência de estagiários\n\n1. Para garantir mais agilidade em relação ao pagamento da bolsa-estágio, informo que, a partir do mês de abril deste ano, serão adotados novos procedimentos para o envio da frequência dos estagiários ao Setor de Pessoal (SePes).\n\n2. A frequência mensal de cada estagiário deverá ser enviada para o endereço de email do SePes até o quinto dia útil de cada mês.\n\n3. As informações do email devem ser complementadas com anexo contendo a planilha de frequência de estagiários, carimbada e assinada pelo chefe do SEst e pelos estagiários.\n\n4. A observância desses procedimentos é essencial para evitar atrasos no pagamento da bolsa.\n\nAtenciosamente,\n\n                                                 (espaço para assinatura)\n                                                 [nome do signatário]\n                                                 Chefe do Setor de Pessoal\n\nCom base no Manual de Redação da Presidência da República, julgue o  item  seguinte , relativo à correspondência oficial hipotética apresentada.\n\nSe, na situação em apreço, o SePes não tivesse determinado o email como via para a remessa da planilha de frequência de estagiários pelo SEst, este poderia fazer uso do memorando.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2015,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":483908,"enunciado":"Goiânia, 21 de janeiro de 2015.\n\nAo Senhor Chefe do Setor de Estágios (SEst) Assunto: Novos procedimentos para envio de frequência de estagiários\n\n1. Para garantir mais agilidade em relação ao pagamento da bolsa-estágio, informo que, a partir do mês de abril deste ano, serão adotados novos procedimentos para o envio da frequência dos estagiários ao Setor de Pessoal (SePes).\n\n2. A frequência mensal de cada estagiário deverá ser enviada para o endereço de email do SePes até o quinto dia útil de cada mês.\n\n3. As informações do email devem ser complementadas com anexo contendo a planilha de frequência de estagiários, carimbada e assinada pelo chefe do SEst e pelos estagiários.\n\n4. A observância desses procedimentos é essencial para evitar atrasos no pagamento da bolsa.\n\nAtenciosamente,\n                                      (espaço para assinatura)\n                                      [nome do signatário]\n                                      Chefe do Setor de Pessoal\n\nCom base no Manual de Redação da Presidência da República, julgue o  item seguinte , relativo à correspondência oficial hipotética apresentada.\n\nAs regras da norma padrão do português seriam respeitadas se, no parágrafo 4 do texto, a expressão “para evitar\" fosse substituída por para que se evite.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2015,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":483909,"enunciado":"Goiânia, 21 de janeiro de 2015.\n\nAo Senhor Chefe do Setor de Estágios (SEst) Assunto: Novos procedimentos para envio de frequência de estagiários\n\n1. Para garantir mais agilidade em relação ao pagamento da bolsa-estágio, informo que, a partir do mês de abril deste ano, serão adotados novos procedimentos para o envio da frequência dos estagiários ao Setor de Pessoal (SePes).\n\n2. A frequência mensal de cada estagiário deverá ser enviada para o endereço de email do SePes até o quinto dia útil de cada mês.\n\n3. As informações do email devem ser complementadas com anexo contendo a planilha de frequência de estagiários, carimbada e assinada pelo chefe do SEst e pelos estagiários.\n\n4. A observância desses procedimentos é essencial para evitar atrasos no pagamento da bolsa.\n\nAtenciosamente,\n\n                                            (espaço para assinatura)\n                                            [nome do signatário]\n                                           Chefe do Setor de Pessoal\n\nCom base no Manual de Redação da Presidência da República, julgue o  item  seguinte, relativo à correspondência oficial hipotética apresentada.\n\nA situação comunicativa mediada pelo texto em questão envolve três interlocutores: o chefe do SePes (comunicador), o chefe do SEst (destinatário direto) e os estagiários (destinatários indiretos).","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2015,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":555215,"enunciado":"Com base no Manual de Redação da Presidência da República, julgue o item a seguir, relativo ao formato e à linguagem das correspondências oficiais.\nA concisão é um princípio da redação oficial que tem por finalidade dar objetividade ao trabalho da administração pública.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2015,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":555216,"enunciado":"Com base no Manual de Redação da Presidência da República, julgue o item a seguir, relativo ao formato e à linguagem das correspondências oficiais.\nNa redação de um documento oficial subscrito por funcionário público de um ministério e endereçado ao ministro desse órgão, deve-se empregar o fecho “Cordialmente,\", por se tratar de destinatário detentor de cargo hierarquicamente superior ao do remetente.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2015,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":555217,"enunciado":"Com base no Manual de Redação da Presidência da República, julgue o item a seguir, relativo ao formato e à linguagem das correspondências oficiais.\nO relatório é um documento que contém informações sobre tarefas executadas e(ou) sobre fatos ou ocorrências no serviço público.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2015,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":555218,"enunciado":"Com base no Manual de Redação da Presidência da República, julgue o item a seguir, relativo ao formato e à linguagem das correspondências oficiais.\nEm uma correspondência oficial, dirigida ao presidente da Câmara dos Deputados, o vocativo a ser usado deve ser “Excelentíssimo Senhor Presidente\".","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2015,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":555219,"enunciado":"Com base no Manual de Redação da Presidência da República, julgue o item a seguir, relativo ao formato e à linguagem das correspondências oficiais.\nEm correspondências encaminhadas pelo presidente da República, é facultativa a apresentação de identificação de cargo ou nome do emissor.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2015,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":825815,"enunciado":"Em relação à correspondência oficial, julgue o próximo item.\n\nSendo a flexibilidade um dos atrativos da comunicação por correio eletrônico, não há necessidade de se evitar a informalidade da linguagem nesse tipo de documento oficial, como o uso de gírias e jargões.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2017,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":825816,"enunciado":"Em relação à correspondência oficial, julgue o próximo item.\n\nO memorando segue, quanto à forma, o modelo do padrão ofício, devendo o destinatário daquele documento ser mencionado pelo cargo que ocupa.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2017,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":872773,"enunciado":"Considerando que o fragmento de texto apresentado integra parte de uma correspondência oficial, julgue o item a seguir.\n\n\n\n\nOs aspectos estruturais e o tema do texto indicam tratar-se de expediente que segue o padrão ofício, ao passo que o seu fechamento sugere tratar-se de documento destinado a autoridade de mesma hierarquia ou de hierarquia inferior à do remetente.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":872774,"enunciado":"Considerando que o fragmento de texto apresentado integra parte de uma correspondência oficial, julgue o item a seguir.\n\n\n\n\nO pronome demonstrativo contido na contração deste refere-se ao órgão ao qual se destina o expediente em questão.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":872775,"enunciado":"Considerando que o fragmento de texto apresentado integra parte de uma correspondência oficial, julgue o item a seguir.\n\n\n\n\nO emprego do advérbio encarecidamente é inadequado, visto que prejudica o caráter impessoal que deve ser adotado em textos oficiais.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":933826,"enunciado":"Quanto à correspondência oficial, julgue o seguinte item.\n\n\n\n\nNas comunicações oficiais dirigidas a particulares, recomenda‐se o emprego do tratamento Vossa Senhoria.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2018,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":933827,"enunciado":"Quanto à correspondência oficial, julgue o seguinte item.\n\n\n\n\nA correspondência oficial entre unidades administrativas de um mesmo órgão é denominada de ofício, que é, portanto, uma modalidade de comunicação interna.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2018,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":943260,"enunciado":"Julgue  o  item  que  se  segue,  considerando  a  correção  gramatical  dos  trechos  apresentados  e  a  adequação  da  linguagem à correspondência  oficial. \nRessalte‐se  que  constitui  competência  desse  setor  a  preparação  de  documentos  de  arquivo  para  processamento eletrônico de dados.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2018,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":943261,"enunciado":"Julgue  o  item  que  se  segue,  considerando  a  correção  gramatical  dos  trechos  apresentados  e  a  adequação  da  linguagem à correspondência oficial. \n\n\n\n\n\nInformo  que  a  documentação  que  Vossa  Senhoria  se  refere  não  se  encontra  disponível,  sendo  que  deve  procurar em outro setor.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2018,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":967240,"enunciado":"Julgue o item, considerando a correção gramatical dos trechos apresentados e a adequação da linguagem à correspondência oficial.\n\n\n\n\nEm atendimento à determinação da Presidência deste Conselho, encaminhamos, em anexo, as informações referentes aos recursos humanos que atuarão no Mutirão do Serviço Social, nos dias 2 e 3 de março de 2019.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":967241,"enunciado":"Julgue o item, considerando a correção gramatical dos trechos apresentados e a adequação da linguagem à correspondência oficial.\n\n\n\n\nInformamos à Vossa Senhoria de que o contrato firmado com a Empresa de Segurança Sempre Alerta foi renovado em 2/1/2019, apartir de onde será necessário contatos permanentes com a direção da empresa.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":967322,"enunciado":"Julgue o item.\n\n\n\n\nAviso é o instrumento por meio do qual dirigentes de órgãos e entidades da administração direta, indireta e fundacional declaram um fato ou uma situação com base em dispositivo legal.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":977647,"enunciado":"De acordo com o Manual de Redação da Presidência da República, julgue o item.\n\n\n\n\nA iniciativa demonstrada no referido manual de classificar expressões empregadas frequentemente em textos oficiais como de uso a ser evitado ou como de uso recomendável atende a dois objetivos: a preferência de renomados gramáticos por determinada forma; e o princípio da clareza e da transparência, que deve nortear a elaboração de toda comunicação oficial.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2018,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":977648,"enunciado":"De acordo com o Manual de Redação da Presidência da República, julgue o item.\n\n\n\n\n\n\n\nÉ considerada como bem construída, segundo os parâmetros do referido manual, a seguinte frase: A comissão para análise das necessidades dos usuários da biblioteca foi criada através de portaria do diretor em 12 de janeiro de 2018.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2018,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":977649,"enunciado":"De acordo com o Manual de Redação da Presidência da República, julgue o item.\n\n\nEstão corretas as alterações feitas por um revisor na seguinte frase redigida por um funcionário: Os custos administrativos foram altos, inclusive as empresas foram obrigadas a dispender recursos consideráveis para cobrir despesas remanescentes. Frase revisada: Os custos administrativos foram altos: as empresas foram obrigadas até mesmo a despender recursos consideráveis para cobrir despesas remanescentes.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2018,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":977650,"enunciado":"De acordo com o Manual de Redação da Presidência da República, julgue o item.\n\n\n\n\n\n\n\nComo modelo de construção exemplar a ser adotada em uma comunicação oficial a um Secretário de Estado, o mencionado manual recomenda: No que pertine ao projeto, cabe-nos ressaltar a Vossa Senhoria que...","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2018,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":986757,"enunciado":"O diretor de unidade do Conselho Regional de Educação Física divulgou, entre seus funcionários e, em especial, entre os professores de educação física, como fonte de estímulo para a inovação das suas práticas com grupos da terceira idade, por meio de uma mensagem de correio eletrônico, e‐mail, a mensagem seguinte.\n\n\n\n\n“Pessoal, leiam o texto do arquivo em anexo. Fico no aguardo da confirmação.”\n\n\n\n\nCom base nessa situação hipotética e nas normas de redação oficial, julgue o item subsequente.\n\n\n\n\nA rapidez de comunicação e a flexibilidade de formato de um e‐mail, ou correio eletrônico, admitem mensagens breves e informais. No entanto, a linguagem empregada na mensagem acima é incompatível com a linguagem de uma comunicação oficial porque desobedece à norma culta da língua.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2018,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":986758,"enunciado":"O diretor de unidade do Conselho Regional de Educação Física divulgou, entre seus funcionários e, em especial, entre os professores de educação física, como fonte de estímulo para a inovação das suas práticas com grupos da terceira idade, por meio de uma mensagem de correio eletrônico, e‐mail, a mensagem seguinte.\n\n\n\n\n“Pessoal, leiam o texto do arquivo em anexo. Fico no aguardo da confirmação.”\n\n\n\n\nCom base nessa situação hipotética e nas normas de redação oficial, julgue o item subsequente.\n\n\n\n\nA praticidade da mensagem eletrônica dispensa o preenchimento de todos os campos do formulário, a exemplo do campo assunto e do recurso de confirmação da leitura, já que um e‐mail não tem qualquer valor documental.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2018,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":988764,"enunciado":"Julgue o próximo item, considerando a correção gramatical dos trechos apresentados e a adequação da linguagem à correspondência oficial.\n\n\n\n\nInformamos a Vossa Senhoria que sua solicitação de material para a organização do XVIII Encontro Nacional de Psicólogos dos Conselhos Regionais de Psicologia foi deferida por esta direção, tendo sido a lista do referido material encaminhada à divisão de compras.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2018,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":988765,"enunciado":"Julgue o próximo item, considerando a correção gramatical dos trechos apresentados e a adequação da linguagem à correspondência oficial.\n\n\n\n\nEncaminhamos, em anexo, a programação do ciclo de palestras Desafios do Trabalho em Equipe e, na oportunidade, reiteramos a importância do tema do mencionado evento para os trabalhos desenvolvidos neste Conselho Regional de Psicologia.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2018,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":989046,"enunciado":"Com relação à correspondência oficial, julgue o item a seguir.\n\n\nO ofício tem como finalidade o tratamento de assuntos oficiais pelos órgãos da Administração Pública entre si e também com particulares.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":989047,"enunciado":"Com relação à correspondência oficial, julgue o item a seguir.\n\n\n\n\nNo memorando, o destinatário deve ser mencionado pelo cargo que ocupa.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":989134,"enunciado":"No que diz respeito à redação oficial de documentos oficiais e às noções de administração pública, julgue o item a seguir.\n\n\n\n\nO padrão ofício pode ser aplicado nos seguintes expedientes: ofício; aviso; e memorando.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":989166,"enunciado":"Julgue o item, considerando a correção gramatical dos trechos apresentados e a adequação da linguagem à correspondência oficial.\nRessalte‐se que, para obter as informações solicitadas, é necessário que Vossa Senhoria comprove seu cadastramento no Sistema Geral de Informações, conforme orientação recebida da Presidência deste Conselho.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":989167,"enunciado":"Julgue o item, considerando a correção gramatical  dos  trechos  apresentados  e  a  adequação  da  linguagem  à  correspondência oficial. \n\nInformo à Vossa Senhoria que, afim de obter tais informações, este signatário promoveu cadastro e solicitou acesso ao Sistema Geral de Informações, todavia, em que pese as tentativas feitas reiteradamente acerca de quinze dias, o acesso ao sistema não está disponível.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":1011355,"enunciado":"Julgue item.\n\n\n\n\nO modo de escrever o parecer técnico deve seguir um modelo preestabelecido, mas deve o parecerista, de toda forma, ser rico na exposição de seu conhecimento técnico e, sobretudo, das questões fáticas, desde que o cliente o entenda, seguindo a regra da coesão, da clareza e da objetividade do texto apresentado.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":1012968,"enunciado":"Julgue o seguinte item, considerando a correção gramatical dos trechos apresentados e a adequação da linguagem à correspondência oficial.\n\n\n\n\nSolicito que Vossa Senhoria me explique porque meu pedido de férias ainda não saiu dessa seção em direção a divisão de pessoal, visto que já fazem dois meses da solicitação inicial.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2018,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":1012969,"enunciado":"Julgue o seguinte item, considerando a correção gramatical dos trechos apresentados e a adequação da linguagem à correspondência oficial.\n\n\n\n\nInformamos que estamos tentando acesso junto ao Sistema de Informações desse Conselho a mais de quinze dias sem sucesso e o mesmo consta como “aguardando autorização”, conforme comprovante em anexo.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2018,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":1013061,"enunciado":"Acerca da redação oficial de documentos oficiais, de administração geral e pública e da Lei n.º 12.527/2011, julgue o item que se segue.\n\n\n\n\nAs comunicações oficiais para autoridades de mesma hierarquia ou de hierarquia inferior devem ter como fecho a expressão “Atenciosamente,”.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2018,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":1033825,"enunciado":"Julgue o item, considerando a correção gramatical dos trechos apresentados e a adequação da linguagem à correspondência oficial.\n\n\n\n\nInformamos que Vossa Senhoria, tem prazo de trinta dias à contar da data do recebimento deste ofício para prestar os devindos esclarecimentos quanto o exercício ilegal da medicina.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":1033826,"enunciado":"Julgue o item, considerando a correção gramatical dos trechos apresentados e a adequação da linguagem à correspondência oficial.\n\n\n\n\nReferente as propostas de credenciamento da instituição, esclarecemos de que há necessidade de comprovação da titulação exigida para a direção do hospital, encaminhado exclusivamente à este CRM.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":1039041,"enunciado":"Julgue o próximo item, relativo à correção gramatical e à adequação da linguagem do trecho apresentado no que diz respeito à correspondência oficial.\n\n\n\n\nInformo à V. S.ª de que os documentos solicitados, foram encaminhados para o endereço eletrônico cadastrado no setor de recursos humanos.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2017,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":1039042,"enunciado":"Julgue o próximo item, relativo à correção gramatical e à adequação da linguagem do trecho apresentado no que diz respeito à correspondência oficial.\n\n\n\n\nEsclarecemos que foram expedidas notificações para o conhecimento da instauração do processo, para a apresentação de informações, justificativas ou defesa e para a cobrança do débito.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2017,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":1039043,"enunciado":"Julgue o próximo item, relativo à correção gramatical e à adequação da linguagem do trecho apresentado no que diz respeito à correspondência oficial.\n\n\n\n\nAcusamos o recebimento do ofício CRN-023/2017, referente à solicitação de uso do auditório deste órgão para a realização de palestra no dia 20 de dezembro de 2017, nos períodos matutino e vespertino, e informamos que o referido espaço não estará disponível na data especificada, quando será realizado evento programado por nossa Diretoria-Geral.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2017,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":1039044,"enunciado":"Julgue o próximo item, relativo à correção gramatical e à adequação da linguagem do trecho apresentado no que diz respeito à correspondência oficial.\n\n\n\n\nTemos a honra de comunicar Vossa Senhoria, que vosso certificado de conclusão do curso Nutrição e Saúde está disponível para retirada em nosso Departamento de Recursos Humanos de segunda-feira à sexta-feira, das 10 horas as 17 horas.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2017,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":1039342,"enunciado":"No que concerne às estruturas linguísticas e gramaticais do texto, julgue o seguinte item.\n\n\n\n\nCom as devidas adaptações redacionais no padrão ofício, o texto poderia integrar um memorando do Ministério da Saúde a ser encaminhado ao presidente da República, informando‐lhe acerca das novas concepções de saúde a serem adotadas no âmbito daquele Ministério, para o que seria necessário inserir, como vocativo, Excelentíssimo Senhor Presidente da República.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2018,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":1055653,"enunciado":"Julgue o iten quanto à correção gramatical dos trechos apresentados e à adequação da linguagem à correspondência oficial.\n\nInformamos à essa Comissão Especial que foi tomado todas as providências necessárias para o encaminhamento do documento de denúncia ao Presidente do Conselho.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":1055654,"enunciado":"Julgue o iten quanto à correção gramatical dos trechos apresentados e à adequação da linguagem à correspondência oficial.\n\nTemos a satisfação de convidar‐lhe enquanto palestrante para participar da Semana do Farmacêutico, conforme programação que segue anexo a este, devendo os trabalhos serem encaminhados via e‐mail.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":1055773,"enunciado":"Com relação à correção gramatical dos trechos apresentados  e à adequação da linguagem à correspondência oficial, julgue o item.\n\n\n\n\nEm  cumprimento  à  determinação  dessa  Presidência,  encaminhamos,  anexas,  a  documentação  e  as  informações  referentes  ao  processo  de  registro  do  Laboratório de Análises Clínicas XYZ.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":1055774,"enunciado":"Com relação à correção gramatical dos trechos apresentados  e à adequação da linguagem à correspondência oficial, julgue o item.\n\n\n\n\nEsta Comissão Especial, em atendimento aos termos do ofício supra, vem respeitosamente à presença de Vossa  Excelência  informar  que  recepcionamos  vosso  ofício  e  estamos efetuando as pesquisas necessárias com vistas  o atendimento do mesmo no menor espaço de  tempo  possível.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":1093401,"enunciado":"Julgue  o  item  quanto  à  correção  gramatical  dos  trechos  apresentados  e  à  adequação  da  linguagem à  correspondência oficial.  \n\n\n\n\nEm razão da importância do objeto tratado neste ofício  e  das  flagrantes  e  graves  irregularidades  identificadas, solicitamos à presidência desse Conselho Regional de Odontologia a adoção das providências cabíveis.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":1093402,"enunciado":"Julgue  o  item  quanto  à  correção  gramatical  dos  trechos  apresentados  e  à  adequação  da  linguagem à  correspondência oficial.  \n\n\n\n\nPerguntamos a esse Conselho Regional de Odontologia se há normas à respeito da prática de acumpultura no processo de anestesia para procedimentos odontológicos especialmente em relação ao reconhecimento e regulamentação destas práticas?","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":1101172,"enunciado":"Informamos que a inclusão de sua empresa no Programa de Desenvolvimento Sustentável foi aceita pela Direção desta Entidade, sendo necessário a confirmação da inscrição no sítio descrito à baixo.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":1101173,"enunciado":"Salientamos na oportunidade, a importância da participação de todos funcionários na apresentação da Comissão de Fiscalização e Controle, que se realizara no dia 3 de dezembro de 2019, no Salão Nobre deste Conselho.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":1252413,"enunciado":"Com base no Manual de Redação da Presidência da República, julgue o item.\n\n\n\n\n\nÉ vedado ao Ministério da Saúde, responsável pelas atividades do SUS, o encaminhamento de minuta de mensagem ao Presidente da República, ainda que fosse para tratar da regulamentação da publicidade de alimentos e da implantação de ações educativas associadas à prevenção e ao enfrentamento dos males à saúde provocados pela má alimentação.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":1748473,"enunciado":"Com base no Manual de Redação da Presidência da República (3.a edição), julgue o item. De acordo com o Manual de Redação da Presidência da República, o destinatário da redação oficial é sempre o serviço público.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":1748474,"enunciado":"Com base no Manual de Redação da Presidência da República (3.a edição), julgue o item.\n\nEm atendimento ao princípio da impessoalidade, o destinatário da comunicação oficial, independentemente de quem seja, deve ser tratado de forma homogênea e impessoal.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":1748475,"enunciado":"Com base no Manual de Redação da Presidência da República (3.a edição), julgue o item.\n\nO seguinte formato de data atende ao padrão ofício estabelecido no Manual de Redação da Presidência da República: Pará, 06/06/2021.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":1748476,"enunciado":"Com base no Manual de Redação da Presidência da República (3.a edição), julgue o item.\n\nO Manual de Redação da Presidência da República prevê a expressão “Respeitosamente” como forma de fecho única para qualquer tipo de comunicação oficial.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":1748477,"enunciado":"Com base no Manual de Redação da Presidência da República (3.a edição), julgue o item.\n\nNas comunicações oficiais que seguem o padrão estabelecido no Manual de Redação da Presidência da República, é obrigatório o uso da vírgula após o vocativo.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":1764799,"enunciado":"Quanto à correção gramatical do trecho apresentado e à adequação da linguagem à correspondência oficial, julgue o item.\nA Coordenação de Segurança deste Conselho tem acompanhado e monitorado os fóruns de discussão onde são divulgados os riscos que tem surgido e que os usuários estão sujeitos, para agir à favor da segurança da informação no Órgão.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":1783794,"enunciado":"Encaminhamos, para análise e aprovação dessa Comissão minuta de projeto que se trata do combate à inatividade física na população adulta do Brasil, reduzindo em 5% o número de pessoas inativas fisicamente no país até 2022.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":1783795,"enunciado":"Solicitamos o posicionamento da Consultoria Jurídica referente à possibilidade de contratação de empresa privada para desenvolver e implantar o Programa Ginástica On Line e outros que julgar pertinente para dar segmento as ações de incentivo na atividade física de nossos colaboradores.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":1783796,"enunciado":"Informamos que os concorrentes que interporam recurso contra o processo de licitação para a contratação de empresa para manutenção e aperfeiçoamento do sistema de informação e comunicação deste Órgão poderá acessar a decisão proferida por meio dos órgãos oficiais de imprensa.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":1829234,"enunciado":"Julgue o item, considerando a correção gramatical dos trechos apresentados e a adequação da linguagem à correspondência oficial. \n\n\n\n\nInformamos-lhe que o envio das informações previamente solicitadas são fundamentais para garantir à inscrição do servidor no evento e se caso o servidor ainda não esteje cadastrado no Sistema, será necessário o envio de autorização da chefia imediata.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":1829235,"enunciado":"Julgue o item, considerando a correção gramatical dos trechos apresentados e a adequação da linguagem à correspondência oficial. \n\n\n\n\nConvido-lhe a participar como palestrante do Ciclo de Debates sobre a Execução do Plano Regional de Combate à Covid-19, a ser realizado em 30 de outubro de 2020, às 9 horas, em forma de videoconferência, devendo, sua presença ser confirmada no prazo de uma semana a contar do recebimento desse.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":1833376,"enunciado":"Acerca da correção gramatical do trecho apresentado e da adequação da linguagem à correspondência oficial, julgue o item.\n\n\n\n\nInformo que a partir de 17 de março de 2020, devem ser adotadas medidas de enfrentamento do novo coronavírus (Covid-19) a serem observadas pelas unidades que compõe este Conselho Regional.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":1833456,"enunciado":"Com relação à redação de documentos oficiais, julgue o item. \n\n\n\n\nPara a elaboração de um documento oficial, é indispensável que o repasse das informações seja literal. Portanto, expressões em língua estrangeira não deverão ser traduzidas.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":1833457,"enunciado":"Com relação à redação de documentos oficiais, julgue o item. \n\n\n\n\nNa redação de documentos oficiais, deve-se sempre priorizar palavras que carreguem um sentido mais comum, dar preferência a afirmações positivas e evitar o jargão técnico.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":1840079,"enunciado":"Julgue o item, considerando a correção gramatical do trecho apresentado e a adequação da linguagem à correspondência oficial. \n\n\n\n\nInformamos que o principal objetivo das visitas de fiscalização e orientação realizadas por fiscais deste Conselho Regional de Serviço Social nas instituições públicas e privadas em cujos quadros funcionais constam assistentes sociais é verificar as condições éticas e técnicas do exercício profissional.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":1865504,"enunciado":"Na redação de correspondências oficiais, deve-se evitar o uso de expressões pleonásticas, tais como “ambos os dois”, e das que formem cacófatos.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":1865505,"enunciado":"Para redigir um texto em que estejam presentes as propriedades da redação oficial, entre elas a concisão, a clareza, a formalidade e a precisão, é condição necessária, mas não suficiente, que o autor possua conhecimento das regras gramaticais.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":1865506,"enunciado":"O emprego de parônimos enquanto recurso de substituição lexical contribui para minimizar, sem prejuízos semânticos, a repetição excessiva de palavras ao longo do texto, a qual, além de demonstrar pobreza vocabular, torna a redação cansativa para o leitor.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":1907589,"enunciado":"Com base nas Normas para Padronização de Documentos da Universidade de Brasília, julgue o seguinte item. \n\n\n\n\nEmbora os pronomes de tratamento se refiram à segunda pessoa gramatical, a concordância verbal com eles deve ser estabelecida com o uso da flexão verbal de terceira pessoa, como no seguinte exemplo, em que a forma pronominal alude ao destinatário da comunicação: Vossa Senhoria encaminhou o documento.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2022,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":1907590,"enunciado":"Com base nas Normas para Padronização de Documentos da Universidade de Brasília, julgue o seguinte item. \n\n\n\n\nO fecho Atenciosamente deve ser empregado somente nas comunicações oficiais cujo destinatário ocupe cargo da mesma hierarquia do remetente.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2022,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":1907591,"enunciado":"Com base nas Normas para Padronização de Documentos da Universidade de Brasília, julgue o seguinte item. \n\n\n\n\nEm atenção à impessoalidade necessária à correspondência oficial, as referidas normas não admitem o uso de verbos conjugados na primeira pessoa gramatical em documentos oficiais da Universidade de Brasília.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2022,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":1913163,"enunciado":"Julgue o item, considerando a correção gramatical dos trechos apresentados e a adequação da linguagem à correspondência oficial. \nVimos solicitar, pelo presente, a visita de uma equipe de inspeção veterinária na Clínica XY por que não têm as condições mínimas para tratar dos animais e nem pessoas qualificadas para o mesmo, sendo que as instalações também são péssimas.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":1913164,"enunciado":"Julgue o item, considerando a correção gramatical dos trechos apresentados e a adequação da linguagem à correspondência oficial. \n\n\n\n\nRessaltamos na oportunidade, que o presente Projeto representa medida importante à institucionalizar instrumentos de gestão voltado para a melhoria das técnicas de manejo animal no campo e, consequentemente, da saúde dos rebanhos.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":1917721,"enunciado":"Quanto à correção gramatical das orações extraídas de exemplos constantes do Manual de Redação da Presidência da República, julgue o item. \n\n\n\n\n“O decreto regulamenta os casos gerais; a portaria, os particulares.”","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":1917722,"enunciado":"Quanto à correção gramatical das orações extraídas de exemplos constantes do Manual de Redação da Presidência da República, julgue o item. \n\n\n\n\n“Os governadores decidiram acatar a decisão. Em seguida, os prefeitos fizeram o mesmo.”","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":1917723,"enunciado":"Quanto à correção gramatical das orações extraídas de exemplos constantes do Manual de Redação da Presidência da República, julgue o item. \n\n\n\n\n“Vossa Senhoria designará vosso substituto.”","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":1926283,"enunciado":"Julgue o item, considerando a correção gramatical dos trechos apresentados e a adequação da linguagem à correspondência oficial. \n\n\n\n\nEncaminhamos a consideração desta Comissão Especial, proposta de aditamento ao contrato que vai ser firmado com o Instituto ABC de Apoio Técnico conforme decisão tomada pelo grupo de trabalho em reunião com a Presidência do Conselho.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":1926284,"enunciado":"Julgue o item, considerando a correção gramatical dos trechos apresentados e a adequação da linguagem à correspondência oficial. \n\n\n\n\nReiteramos, por meio deste, pedido já realizado diversas vezes, de material indispensável ao serviço de reprografia do setor de atendimento ao público, como resma de papel A4 e o tonner da impressora que acabaram fazem dois meses.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["redacao_oficial","ortografia"]},{"id":1939957,"enunciado":"Julgue o item, considerando a correção gramatical dos trechos apresentados e a adequação da linguagem à correspondência oficial. \n\n\n\n\nInformamos que acerca de dois meses, foi disponibilizado à todos os colaboradores deste órgão uma plataforma, onde podem acessar serviços de atendimento on-line de psicologia, bastando  inscrever-se na lista de interessados constante na Secretaria de Recursos Humanos.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":1955646,"enunciado":"Julgue o item, considerando a correção gramatical dos trechos apresentados e a adequação da linguagem à correspondência oficial. \n\n\n\n\nSolicitamos a essa chefia para instruí os novos agentes administrativos a realizar serviços de suporte operacional e administrativo, tendo em vista o funcionamento desta Autarquia, organizar o processo de arquivos de documentos, separando, ordenando e arquivando os documentos, por tipo e origem, conforme às regras e procedimentos estabelecidos.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":1955647,"enunciado":"Julgue o item, considerando a correção gramatical dos trechos apresentados e a adequação da linguagem à correspondência oficial. \n\n\n\n\nEsclarecemos que, para nós, não é certo os levantamentos de dados referentes a assuntos administrativos, a fim de serem utilizados por terceiros interessados nos dados necessários ao seu controle, para esclarecimento e despacho com a chefia, por isso não concordamos com a sua iniciativa.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":2096530,"enunciado":"Com base na situação hipotética acima, julgue o próximo item, acerca de redação oficial.\n\n\n\n\nO chefe da seção de comunicação social deve encaminhar, em seu nome, a todas as seções, a matéria sobre o evento, em forma de memorando.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2006,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":2096531,"enunciado":"Com base na situação hipotética acima, julgue o próximo item, acerca de redação oficial.\n\n\n\n\nAo encaminhar a matéria à diretoria, o chefe da seção de comunicação social deverá empregar, na correspondência dirigida ao diretor, a seguinte fórmula: Digníssimo Sr. Dr. Fulano de Tal Diretor.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2006,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":2096532,"enunciado":"Com base na situação hipotética acima, julgue o próximo item, acerca de redação oficial.\n\n\n\n\nQualquer que seja a correspondência de encaminhamento acerca da divulgação do evento, é dispensável o fecho, por se tratar de comunicação de circulação interna do Banco.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2006,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":2096533,"enunciado":"Com base na situação hipotética acima, julgue o próximo item, acerca de redação oficial.\n\n\n\n\nSeja qual for a forma de encaminhamento da matéria de divulgação sobre o seminário, o chefe da seção de comunicação social deverá enviar texto de que conste cabeçalho ou timbre.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2006,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":2134811,"enunciado":"A respeito da redação oficial, julgue o item.\n\n\n\n\nNo padrão ofício, o texto do documento deve obedecer a um padrão estrutural, de modo a conter introdução, desenvolvimento e conclusão. Porém, tal estrutura deve ser modificada quando se tratar de um texto utilizado para encaminhar documentos, visto que a organização demanda apenas a introdução e o desenvolvimento.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":2134812,"enunciado":"A respeito da redação oficial, julgue o item.\n\n\n\n\nO correto emprego dos pronomes de tratamento satisfaz, unicamente e em sua totalidade, o princípio da formalidade das comunicações oficiais.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":2134813,"enunciado":"A respeito da redação oficial, julgue o item.\n\n\n\n\nNa redação de documentos oficiais, a grafia de siglas obedece a uma série de regras, entre elas a formação do plural, o qual admite o uso da letra “s” minúscula e sem o apóstrofo, exceto quando a sigla já terminar com a letra “s”, visto que, nesse caso, o plural é determinado pelo uso do artigo.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["redacao_oficial","ortografia"]},{"id":2134814,"enunciado":"A respeito da redação oficial, julgue o item.\n\n\n\n\nQuanto às mensagens em meio eletrônico, o emissor deve, em atendimento aos princípios da eficácia e da eficiência na comunicação, prescindir da forma, cuja exigência é própria aos documentos tradicionais.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":2134815,"enunciado":"A respeito da redação oficial, julgue o item.\n\n\n\n\nDe acordo com o Manual de Redação Oficial da Presidência da República, as frases que contêm citações estão submetidas às regras de correto posicionamento das aspas, as quais devem anteceder os pontos de interrogação e de exclamação quando eles não compuserem a citação.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":2134816,"enunciado":"A respeito da redação oficial, julgue o item.\n\n\n\n\nNa redação de e‑mails de caráter oficial, recomenda‑se que, sempre que possível, as imagens sejam inseridas no corpo da mensagem, sobretudo quando se tratar do logotipo do ente público de origem, cuja imagem deve constar junto à assinatura do emissor.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":2181009,"enunciado":"Em relação à correspondência oficial, de acordo com o Manual de Redação da Presidência da República (MRPR), julgue o item.\nDe acordo com o MRPR, a comunicação realizada por meio de um expediente oficial pode ser relativa tanto às atribuições do órgão que comunica quanto às atribuições da pessoa que assina o expediente.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":2393897,"enunciado":"Julgue o item que se segue, de acordo com o Manual de Redação da Presidência da República.\n\n\n\n\nO padrão ofício corresponde a um tipo de diagramação usado em determinados textos oficiais.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":2393898,"enunciado":"Julgue o item que se segue, de acordo com o Manual de Redação da Presidência da República.\n\n\n\n\nUma das características de um texto oficial deve ser a concisão.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":2445567,"enunciado":"Em relação à redação oficial de documentos oficiais, julgue o item.\n\n\n\n\nEntre os atributos da redação oficial, o da clareza complementa o da precisão e caracteriza-se pela manifestação do pensamento ou da ideia com palavras sinônimas, com propósito estilístico.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":2445568,"enunciado":"Em relação à redação oficial de documentos oficiais, julgue o item.\n\n\n\n\nNas comunicações oficiais, deve ser utilizado o vocativo “Excelentíssimo Senhor” ou “Excelentíssima Senhora”, seguido do respectivo cargo, quando se tratar de autoridade chefe do Poder Executivo, do Poder Legislativo ou do Poder Judiciário.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":2445569,"enunciado":"Em relação à redação oficial de documentos oficiais, julgue o item.\n\n\n\n\nAs comunicações entre unidades administrativas do mesmo órgão devem ser realizadas por meio de ofício.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":2467749,"enunciado":"De acordo com o Manual de Redação da Presidência da República, julgue o item, acerca da redação oficial.\n\n\n\n\nA ideia de concisão guarda um conceito de eficiência, porque se espera transmitir o máximo de informação com o mínimo de palavras.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":2467750,"enunciado":"De acordo com o Manual de Redação da Presidência da República, julgue o item, acerca da redação oficial.\n\n\n\n\nA referência é um mecanismo de coesão, mas não se pode fazer a mesma afirmação quanto à substituição.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":2467751,"enunciado":"De acordo com o Manual de Redação da Presidência da República, julgue o item, acerca da redação oficial.\n\n\n\n\nA formalidade das comunicações administrativas só deve ser observada em documentos impressos.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":2467752,"enunciado":"De acordo com o Manual de Redação da Presidência da República, julgue o item, acerca da redação oficial.\n\n\n\n\nO uso da norma padrão implica empregar a língua de modo rebuscado.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":2467753,"enunciado":"De acordo com o Manual de Redação da Presidência da República, julgue o item, acerca da redação oficial.\n\n\n\n\nExposição de motivos é o expediente dirigido ao presidente da República ou ao vice‑presidente, para se propor alguma medida, para submeter projeto de ato normativo à sua consideração ou para informar de determinado assunto.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":2505139,"enunciado":"De acordo com a redação oficial de documentos oficiais, julgue o item abaixo.\nNa redação oficial, o uso do padrão culto significa o emprego da linguagem que acata os preceitos da gramática formal e emprega um léxico compartilhado pelo conjunto dos usuários da língua.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":2505140,"enunciado":"De acordo com a redação oficial de documentos oficiais, julgue o item abaixo.\nNa estrutura de diagramação dos documentos oficiais, a comunicação oficial para a expedição de documentos entre unidades administrativas de órgãos distintos é denominada memorando.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":2520111,"enunciado":"No que diz respeito à redação oficial de documentos oficiais, julgue o item abaixo. \n\n\n\n\nNa redação oficial, o uso do padrão culto significa o emprego da linguagem de modo rebuscado ou com o uso de figuras de linguagem próprias do estilo literário.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":2520112,"enunciado":"No que diz respeito à redação oficial de documentos oficiais, julgue o item abaixo. \n\n\n\n\nA estrutura de diagramação dos documentos oficiais é denominada padrão ofício.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":2562865,"enunciado":"Com base no Manual de Redação da Presidência da República (MRPR), julgue o item a seguir, acerca da redação oficial.\n\nA redação oficial deve caracterizar‑se, também, pela clareza.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":2562866,"enunciado":"Com base no Manual de Redação da Presidência da República (MRPR), julgue o item a seguir, acerca da redação oficial.\n\nO destinatário de um expediente oficial deve receber o vocativo “Excelentíssimo(a)”, seguido de seu nome e do cargo que ocupa.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":2562867,"enunciado":"Com base no Manual de Redação da Presidência da República (MRPR), julgue o item a seguir, acerca da redação oficial.\n\nNo caso da redação oficial, o destinatário é o público, uma instituição privada ou outro órgão ou entidade pública.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":2562868,"enunciado":"Com base no Manual de Redação da Presidência da República (MRPR), julgue o item a seguir, acerca da redação oficial.\n\nA redação oficial é a utilizada no serviço público para legalizar uma situação.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":3198478,"enunciado":"Quanto à redação oficial de documentos oficiais, julgue o item seguinte.\n\n\n\n\nPara o cumprimento do atributo da objetividade, é fundamental que o redator saiba de antemão qual é a ideia principal e quais são as secundárias.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":3198479,"enunciado":"Quanto à redação oficial de documentos oficiais, julgue o item seguinte.\n\n\n\n\nO atributo da formalidade e da padronização não se aplica às comunicações realizadas em meio eletrônico.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":3198480,"enunciado":"Quanto à redação oficial de documentos oficiais, julgue o item seguinte.\n\n\n\n\nNo padrão ofício, a identificação do expediente compreende o nome do documento, a indicação de numeração, e as informações do documento, como ano e siglas usuais do setor que expede o documento.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":3638078,"enunciado":"De acordo com o Manual de Redação da Presidência da República, julgue o item a seguir, acerca da redação oficial. \n\n\n\n\nDada a sua natureza oficial, os documentos oficiais caracterizam‑se pelo emprego de uma padronização na linguagem, denominada padrão oficial de linguagem, que difere da norma padrão da língua portuguesa.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":3638079,"enunciado":"De acordo com o Manual de Redação da Presidência da República, julgue o item a seguir, acerca da redação oficial. \n\n\n\n\nA impessoalidade dos documentos oficiais é consequência do princípio constitucional de impessoalidade que regre a Administração Pública.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":3638080,"enunciado":"De acordo com o Manual de Redação da Presidência da República, julgue o item a seguir, acerca da redação oficial. \n\n\n\n\nUma mensagem de correio eletrônico (e‑mail) terá valor documental se for enviada a partir de um servidor que use a extensão “.gov.br”.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":3638081,"enunciado":"De acordo com o Manual de Redação da Presidência da República, julgue o item a seguir, acerca da redação oficial. \n\n\n\n\nEstá correta a identificação de um ofício de número 36 emitido pelo CAU‑MA neste ano de 2025: Ofício nº 36/2025 – CAU‑MA.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":3759520,"enunciado":"Acerca da redação oficial, julgue o item a seguir. \n\n\n\n\nOs e-mails institucionais, por se tratarem de mensagens trocadas em meio eletrônico, prescindem da linguagem formal e podem empregar o mesmo tom de comunicação utilizado nas redes sociais.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":3759521,"enunciado":"Acerca da redação oficial, julgue o item a seguir. \n\nPode‑se definir como conciso aquele texto que possibilita imediata compreensão pelo leitor.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":3759522,"enunciado":"Acerca da redação oficial, julgue o item a seguir. \n\nO aviso, o ofício e o memorando foram uniformizados no que se conhece atualmente como o padrão ofício.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":3759523,"enunciado":"Acerca da redação oficial, julgue o item a seguir. \n\nEmprega‑se itálico em títulos de publicações (livros, revistas, jornais, periódicos etc.) ou títulos de congressos, conferências, slogans, lemas sem o uso de aspas (com inicial maiúscula em todas as palavras, inclusive nas de ligação).","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":3759589,"enunciado":"Julgue o item a seguir, acerca da comunicação nas organizações públicas.\n\nNa redação oficial de documentos, a introdução é a parte do texto na qual o assunto é detalhado e, se o texto apresentar mais de uma ideia, elas devem ser tratadas em parágrafos distintos.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":3759590,"enunciado":"Julgue o item a seguir, acerca da comunicação nas organizações públicas.\n\nPor ser informal, o texto das mensagens eletrônicas oficiais desobriga a iniciação por uma saudação.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":3759591,"enunciado":"Julgue o item a seguir, acerca da comunicação nas organizações públicas.\n\nEntre as características específicas dos documentos públicos, está a fidedignidade, assegurando que o seu conteúdo deve representar, de forma precisa e completa, as atividades ou fatos que os originaram.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":3759680,"enunciado":"Acerca da redação oficial e de seus aspectos, julgue o item seguinte.\n\n\n\n\nO cabeçalho é utilizado apenas na primeira página do documento, centralizado na área determinada pela formatação.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":3759681,"enunciado":"Acerca da redação oficial e de seus aspectos, julgue o item seguinte.\n\n\n\n\nUm dos erros comuns cometidos pelo servidor público – e que deve ser contornado – é a atitude de tomar como de conhecimento geral algo que pode ser desconhecido pelo cidadão.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":3759682,"enunciado":"Acerca da redação oficial e de seus aspectos, julgue o item seguinte.\n\n\n\n\nEm relação ao pronome possessivo referido a pronome de tratamento, está correta a concordância na oração: “Vossa senhoria escolherá o vosso camarote no evento para o qual foi convidado”.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":3759683,"enunciado":"Acerca da redação oficial e de seus aspectos, julgue o item seguinte.\n\n\n\n\nIndependentemente de se tratar de cidadão, entidade privada ou outro órgão ou entidade pública, a comunicação ao destinatário pode ser feita sempre concebendo‑o de forma heterogênea e pessoal.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":3781404,"enunciado":"No que diz respeito à redação oficial, julgue o item a seguir.\n\n\n\n\nConforme o Manual de Redação da Presidência da República, para que haja comunicação, são necessários os seguintes participantes: alguém que comunique, algo a ser comunicado e alguém que receba essa comunicação.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":3781405,"enunciado":"No que diz respeito à redação oficial, julgue o item a seguir.\n\n\n\n\nA precisão é antes uma qualidade do que uma característica do texto oficial. Preciso é o texto que consegue transmitir o máximo de informações com o mínimo de palavras.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":3781406,"enunciado":"No que diz respeito à redação oficial, julgue o item a seguir.\n\n\n\n\nAs comunicações administrativas devem ser sempre formais, isto é, obedecer a certas regras de forma. Isso é válido tanto para as comunicações feitas em meio eletrônico, salvo quando estas forem informações classificadas como pessoais.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":3781407,"enunciado":"No que diz respeito à redação oficial, julgue o item a seguir.\n\n\n\n\nUma servidora pública precisou enviar uma comunicação oficial ao vice‑presidente da República, juntamente com um convite. Considerando que o interlocutor é homem, ela deverá utilizar o pronome “Vossa Excelência (V.Exa)” e o adjetivo “convidado”.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":3781408,"enunciado":"No que diz respeito à redação oficial, julgue o item a seguir.\n\n\n\n\nEscrevem‑se sem hífen os cargos formados pelo adjetivo geral: diretor geral, relator geral, ouvidor geral.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["redacao_oficial","hifen"]},{"id":3781409,"enunciado":"No que diz respeito à redação oficial, julgue o item a seguir.\n\n\n\n\nO memorando, que hoje faz parte do que se chama padrão ofício, era expedido entre unidades administrativas de órgãos diferentes.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":3781480,"enunciado":"Acerca da comunicação organizacional, julgue o item a seguir.\n\n\n\n\nA expressão “Ao digníssimo Senhor Diretor do Departamento” constitui amostra de uso de formalidade e vocativo na redação de documentos oficiais.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":3781481,"enunciado":"Acerca da comunicação organizacional, julgue o item a seguir.\n\n\n\n\nA construção “O objetivo da presente é para informar que devido ao fato de que a verba não foi liberada ainda, o projeto será temporariamente suspenso até segunda ordem” representa que o documento oficial atende aos requisitos de clareza e concisão.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":3937109,"enunciado":"De acordo com os princípios e com as características da redação oficial de documentos, julgue o item seguinte.\n\n\n\n\nA redação oficial caracteriza‑se pela clareza, pela objetividade e pela padronização da linguagem, com o objetivo de assegurar a compreensão uniforme das informações transmitidas.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2026,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":3937110,"enunciado":"De acordo com os princípios e com as características da redação oficial de documentos, julgue o item seguinte.\n\n\n\n\nA impessoalidade é um princípio da redação oficial e implica a eliminação de marcas de subjetividade e de opiniões pessoais nos documentos administrativos.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2026,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":3937111,"enunciado":"De acordo com os princípios e com as características da redação oficial de documentos, julgue o item seguinte.\n\n\n\n\nA utilização de linguagem rebuscada e excessivamente técnica é recomendada na redação oficial, pois demonstra formalidade e eleva o nível do documento administrativo.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2026,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":3937112,"enunciado":"Acerca dos tipos de documentos administrativos e dos procedimentos de protocolo documental, julgue o item a seguir.\n\n\n\n\nO memorando é um documento administrativo utilizado para a comunicação interna entre unidades de uma mesma instituição, com a finalidade predominantemente informativa ou solicitativa.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2026,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":3937113,"enunciado":"Acerca dos tipos de documentos administrativos e dos procedimentos de protocolo documental, julgue o item a seguir.\n\n\n\n\nO ofício é um documento administrativo de uso exclusivo para comunicações internas, não sendo empregado no relacionamento formal com entidades ou pessoas externas à instituição.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2026,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":3951991,"enunciado":"Com base no Manual de Redação da Presidência da República, julgue o item a seguir, acerca da redação oficial.\n\n\n\n\nO atributo da clareza não se esgota na mera publicação do texto, estendendo‑se à necessidade de transparência e de compreensão imediata pelo cidadão, o que exige o uso de palavras simples em seu sentido comum, exceto em comunicações acerca dos assuntos técnicos.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2026,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":3951992,"enunciado":"Com base no Manual de Redação da Presidência da República, julgue o item a seguir, acerca da redação oficial.\n\n\n\n\nNa elaboração de ofícios, a linha pontilhada é utilizada exclusivamente para indicar supressões de texto quando se reproduz dispositivo legal, não sendo aplicável para indicar a manutenção de texto em artigos alterados por atos normativos.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2026,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":3951993,"enunciado":"Com base no Manual de Redação da Presidência da República, julgue o item a seguir, acerca da redação oficial.\n\n\n\n\nEm ofícios que contenham três ou mais parágrafos, a numeração deve iniciar desde o primeiro parágrafo, excetuando‑se dessa contagem apenas o vocativo e o fecho.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2026,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":4014745,"enunciado":"Acerca da comunicação interna e externa e da redação oficial de documentos nas organizações públicas, julgue o item seguinte.\n\n\n\n\nA construção “Informamos que, no momento, estamos procedendo com a antecipação prévia do cronograma, visando obter um ganho de tempo futuro” constitui um exemplo de concisão na escrita de textos oficiais.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2026,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":4014746,"enunciado":"Acerca da comunicação interna e externa e da redação oficial de documentos nas organizações públicas, julgue o item seguinte.\n\n\n\n\nEm regra, é vedado, na comunicação com agentes públicos federais, o uso das formas de tratamento, ainda que abreviadas, de ilustre ou ilustríssimo.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2026,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":4014747,"enunciado":"No que diz respeito aos tipos de documentos administrativos e às etapas de protocolo nas organizações públicas, julgue o item a seguir.\n\n\n\n\nA certidão administrativa, ao contrário da declaração, espelha um registro preexistente e permanente na repartição, como a certidão de tempo de serviço de um servidor público.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2026,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":4014748,"enunciado":"No que diz respeito aos tipos de documentos administrativos e às etapas de protocolo nas organizações públicas, julgue o item a seguir.\n\n\n\n\nO requerimento é um documento administrativo utilizado para solicitar um direito ou um interesse particular, dirigindo‑se geralmente de baixo para cima na hierarquia funcional da Administração Pública.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2026,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":4019466,"enunciado":"Acerca da comunicação organizacional, da redação oficial e dos tipos de documentos administrativos, julgue o item seguinte.\n\n\n\n\nEm documentos oficiais externos, a linguagem deve observar rigorosamente os princípios de impessoalidade, clareza, concisão, formalidade e uso do padrão culto da língua, vedando‑se o emprego de termos coloquiais ou expressões ambíguas.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2026,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":4019467,"enunciado":"Acerca da comunicação organizacional, da redação oficial e dos tipos de documentos administrativos, julgue o item seguinte.\n\n\n\n\nO ofício, o memorando e a ata são documentos administrativos que, embora possuam finalidades distintas, compartilham a necessidade de registro formal, datação e identificação dos responsáveis pela elaboração.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2026,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":4241181,"enunciado":"A exposição de motivos interministerial deve ser assinada por todos os ministros de Estado interessados no assunto nela tratado e pode, em certos casos, ser publicada no Diário Oficial da União.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2012,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":4241182,"enunciado":"Senhor Conselheiro,\nEnviamos, anexa, a ata da última reunião de planejamento presidida por Vossa Senhoria, para conferência e assinatura. Solicitamos que a devolução do documento, devidamente conferido e assinado, não ultrapasse três dias úteis.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2012,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":4295010,"enunciado":"Considerando os aspectos estruturais e linguísticos das correspondências oficiais previstos no Manual de Redação da Presidência da República, julgue o item que se segue.\n\nCaso um ministro da Primeira Turma do STJ tenha de encaminhar um documento a um ministro da Quarta Turma desse mesmo tribunal, a comunicação a ser expedida para esse fim será o aviso, e o fecho a ser utilizado será “Cordialmente”.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2015,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":4295011,"enunciado":"Considerando os aspectos estruturais e linguísticos das correspondências oficiais previstos no Manual de Redação da Presidência da República, julgue o item que se segue.\n\nSempre que possível, os despachos ao memorando devem ser registrados no próprio documento, para simplificar o processo e garantir maior transparência às decisões tomadas.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2015,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":4295012,"enunciado":"Considerando os aspectos estruturais e linguísticos das correspondências oficiais previstos no Manual de Redação da Presidência da República, julgue o item que se segue.\n\nA exposição de motivos é uma comunicação oficial dirigida ao presidente da República ou ao vice-presidente por um ministro de Estado e pode ser interministerial, ou seja, assinada por mais de um ministro.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2015,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":4295013,"enunciado":"Considerando o fragmento da comunicação oficial hipotética anteriormente apresentado, julgue o próximo item com base no Manual de Redação da Presidência da República.\n\nA linguagem empregada no documento hipotético em questão atende aos princípios de clareza, concisão e uso de linguagem formal e, portanto, é adequada à comunicação oficial.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2015,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":4295014,"enunciado":"Considerando o fragmento da comunicação oficial hipotética anteriormente apresentado, julgue o próximo item com base no Manual de Redação da Presidência da República.\n\nA estrutura do documento apresentado é adequada à composição de um ofício.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2015,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":4295015,"enunciado":"Tendo como referência a comunicação hipotética apresentada, julgue o item a seguir à luz das Normas para Padronização de Documentos da Universidade de Brasília.\n\nO expediente em análise deveria ter sido redigido sob a forma de carta, devido ao fato de ser essa a comunicação oficial adequada para agradecimentos.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2015,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":4295016,"enunciado":"Tendo como referência a comunicação hipotética apresentada, julgue o item a seguir à luz das Normas para Padronização de Documentos da Universidade de Brasília.\n\nConsiderando-se o emprego de pronomes nas comunicações oficiais, poder-se-iam empregar, alternativamente, as formas pronominais possessivas vosso e vossos na terceira pessoa.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2015,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":4295017,"enunciado":"Tendo como referência a comunicação hipotética apresentada, julgue o item a seguir à luz das Normas para Padronização de Documentos da Universidade de Brasília.\n\nNo corpo do documento apresentado, faculta-se o emprego de negrito ou de aspas no nome Departamento de Registro Acadêmico, com o intuito de destacá-lo.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2015,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":4295018,"enunciado":"Tendo como referência a comunicação hipotética apresentada, julgue o item a seguir à luz das Normas para Padronização de Documentos da Universidade de Brasília.\n\nO número do documento apresentado segue a obrigatoriedade de que, em ofícios, assim como em memorandos e resoluções, sejam preenchidos com zeros os espaços dos números compostos por menos de quatro dígitos.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2015,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":4295019,"enunciado":"Com base nas Normas para Padronização de Documentos da Universidade de Brasília, julgue o item a seguir, relativo ao formato e à linguagem de correspondências oficiais.\n\n\n\n\nPelo fato de o reitor estar em nível hierárquico superior ao dos demais servidores da UnB, deve-se empregar o fecho Respeitosamente, nas correspondências internas a ele dirigidas.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2015,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":4295020,"enunciado":"Com base nas Normas para Padronização de Documentos da Universidade de Brasília, julgue o item a seguir, relativo ao formato e à linguagem de correspondências oficiais.\n\n\nEm documentos oficiais destinados ao reitor da UnB, devem ser empregados o pronome de tratamento Vossa Excelência e o vocativo Excelentíssimo Senhor Reitor.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2015,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":4295021,"enunciado":"Com base nas Normas para Padronização de Documentos da Universidade de Brasília, julgue o item a seguir, relativo ao formato e à linguagem de correspondências oficiais.\n\n\n\n\nA ata, documento que relata, objetivamente, as discussões, as propostas e as deliberações ocorridas em reuniões no âmbito da instituição, deve ser redigida com linguagem estritamente técnica e assinada, preferencialmente, por todos os membros presentes na reunião.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2015,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":4295022,"enunciado":"Com base no trecho de documento acima, adaptado da página eletrônica www.unb.br, e nas Normas para Padronização de Documentos da Universidade de Brasília, julgue os itens subsequentes.\n\nO conteúdo do documento permite classificá-lo como memorando.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":4295023,"enunciado":"Com base no trecho de documento acima, adaptado da página eletrônica www.unb.br, e nas Normas para Padronização de Documentos da Universidade de Brasília, julgue os itens subsequentes.\n\nNo rodapé do documento, devem constar, em fonte 12, dados que identifiquem o endereço do remetente, como o nome da Universidade de Brasília e da unidade acadêmica, o número de telefone e o endereço eletrônico.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":4295024,"enunciado":"Com base no trecho de documento acima, adaptado da página eletrônica www.unb.br, e nas Normas para Padronização de Documentos da Universidade de Brasília, julgue os itens subsequentes.\n\nA indicação do servidor pelo centro de custo pode ser feita no formulário específico de despacho.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":4295025,"enunciado":"Com base no trecho de documento acima, adaptado da página eletrônica www.unb.br, e nas Normas para Padronização de Documentos da Universidade de Brasília, julgue os itens subsequentes.\n\nSem prejuízo às ideias originais do texto e às Normas para Padronização de Documentos da UnB, a sentença “Certos de podermos contar com a sua colaboração” poderia ser reescrita desta forma: Certos de podermos contar com a colaboração de Vossa Excelência.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":4295026,"enunciado":"No item a seguir, é apresentado um trecho de texto, que deve ser julgado certo se estiver correto e adequado para compor o tipo de correspondência oficial indicada em negrito, ou errado, em caso contrário.\nAta – O Secretário tomou a palavra e esclareceu que, de acordo com pesquisa realizada pela CNI, aproximadamente 70% das empresas no Brasil sofrem dificuldades decorrentes da má qualificação profissional. E apesar de a maioria oferecer treinamento na própria empresa, para contornar o atraso, a deficiência na qualidade do ensino básico foi apontada como elemento limitante para a capacitação. Em muitos casos, é necessário retomar estágios fundamentais para auxiliar o aluno a alcançar o nível técnico desejado.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2013,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":4295027,"enunciado":"No item a seguir, é apresentado um trecho de texto, que deve ser julgado certo se estiver correto e adequado para compor o tipo de correspondência oficial indicada em negrito, ou errado, em caso contrário.\nRelatório – Constatou-se que há no país 2,2 milhões de jovens entre os dezoito e os vinte e quatro anos de idade fora da escola e do mercado de trabalho. Além disso, o nível de escolaridade dos trabalhadores é um dado significativo: hoje, 5,6 milhões de empregados na indústria nacional não possuem sequer o ensino médio. Com o intuito de mudar esse quadro, sugestões estão sendo discutidas nos estados para a criação de uma agenda profissionalizante no âmbito do movimento Educação para o Mundo do Trabalho.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2013,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":4295028,"enunciado":"Em cada um do item a seguir, é apresentado um trecho de texto, que deve ser julgado certo se estiver correto e adequado para compor o tipo de correspondência oficial indicada em negrito, ou errado, em caso contrário.\nMemorando – Esclarecemos à Vossa Senhoria que entre as propostas debatidas, com a participação de reitores universitários, representantes de governos e empresários, figurou o fortalecimento dos ensinos básico e médio, com a valorização dos professores e a adoção de iniciativas para a melhoria substancial da gestão escolar. Para fortalecer esses objetivos em 2011, o governo federal lançou o Programa Nacional de Acesso ao Ensino Técnico e Emprego (PRONATEC), visando a abrir 8 milhões de vagas até 2014.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2013,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":4295029,"enunciado":"Em conformidade com o disposto no Manual de Redação da Presidência da República, julgue o item subsequente\n\nAinda que não haja definição de uma forma rígida para a estrutura das comunicações por email, devem-se observar a impessoalidade e o uso do padrão culto da linguagem nesse tipo de comunicação.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2013,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":4295030,"enunciado":"Em conformidade com o disposto no Manual de Redação da Presidência da República, julgue o item subsequente.\n\nNo seguinte fragmento de documento oficial, o pronome de tratamento dirigido a secretário de governo está adequadamente empregado: Reverendíssimo Senhor Secretário.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2013,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":4295031,"enunciado":"Em conformidade com o disposto no Manual de Redação da Presidência da República, julgue o item subsequente.\n\nO uso de pronomes de tratamento, a forma dos fechos e a identificação do signatário são aspectos comuns entre as modalidades de comunicação oficial.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2013,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":4295032,"enunciado":"Em conformidade com o disposto no Manual de Redação da Presidência da República, julgue o item subsequente.\n\nSalvo se estiverem organizados em itens, os parágrafos de um memorando devem ser numerados.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2013,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":4295033,"enunciado":"Em conformidade com o disposto no Manual de Redação da Presidência da República, julgue o item subsequente.\n\nO seguinte trecho de documento oficial atende aos requisitos de impessoalidade e de uso do padrão culto da linguagem: Em sua comunicação, Vossa Excelência ressalva a necessidade de que fossem levadas em consideração as características socioeconômicas regionais.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2013,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":4295034,"enunciado":"Considerando a definição apresentada, julgue o próximo item, relativo à redação oficial.\n\n\n\n\nEm um documento a ser enviado pelo ministro presidente do Superior Tribunal Militar ao ministro presidente do Supremo Tribunal Federal, é adequado o emprego do pronome de tratamento Vossa Senhoria como vocativo, pois ambos (remetente e destinatário) ocupam cargos de mesmo nível hierárquico.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":4295035,"enunciado":"Considerando a definição apresentada, julgue o próximo item, relativo à redação oficial.\n\n\n\n\nO trecho a seguir é adequado, quanto ao formato e à linguagem, para compor um memorando destinado à comunicação entre os seguintes setores do Superior Tribunal Militar: Diretoria de Pessoal e Coordenadoria do Plano de Saúde da Justiça Militar da União (JMU).\n\n\n\n\n                                                                                Em 8 de fevereiro de 2018\n\nAo Senhor Coordenador do Plano de Saúde da JMU\n\n\n\n\nAssunto: Inclusão de novos servidores no plano de saúde do órgão","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]},{"id":4295036,"enunciado":"Considerando a definição apresentada, julgue o próximos item, relativo à redação oficial.\n\n\n\n\nO ofício e o aviso são idênticos quanto à finalidade: ambos tratam de assuntos oficiais entre órgãos da administração pública.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["redacao_oficial"]}];
